// Service names are split over two display lines (e.g. "WEB" / "DEVELOPMENT").
// French needs a different word order ("DÉVELOPPEMENT" / "WEB"), so these are
// translated as whole phrases rather than line by line.
const serviceTitleLines: Record<string, readonly string[]> = {
  "WEB DEVELOPMENT": ["DÉVELOPPEMENT", "WEB"],
  "SOFTWARE DEVELOPMENT": ["DÉVELOPPEMENT", "LOGICIEL"],
  "MOBILE APPLICATIONS": ["APPLICATIONS", "MOBILES"],
  "AI & MACHINE LEARNING": ["IA ET APPRENTISSAGE", "AUTOMATIQUE"],
  "DATA & ANALYTICS": ["DONNÉES ET", "ANALYTIQUE"],
  "AUTOMATION & INTEGRATIONS": ["AUTOMATISATION ET", "INTÉGRATIONS"],
};

/** [container, line] selectors for every place a service's display lines render. */
const serviceTitleSlots: [string, string][] = [
  [".oveliq-svc-title__difference", ".oveliq-svc-title__line"],
  [".oveliq-svc-acc__display", ":scope > span"],
  [".oveliq-ip-title", ":scope > span"],
];

function localizeServiceTitles() {
  for (const [containerSelector, lineSelector] of serviceTitleSlots) {
    document.querySelectorAll<HTMLElement>(containerSelector).forEach((container) => {
      const lines = Array.from(container.querySelectorAll<HTMLElement>(lineSelector));
      const key = lines.map((line) => (line.textContent ?? "").trim()).join(" ");
      const french = serviceTitleLines[key];
      if (!french || french.length !== lines.length) return;
      lines.forEach((line, index) => {
        // Write only on change (see localizeVisibleCopy) and keep React's text node.
        const text = line.firstChild;
        if (text?.nodeType === Node.TEXT_NODE && text.nodeValue !== french[index]) text.nodeValue = french[index];
      });
    });
  }
}

function localizeVisibleCopy() {
  localizeServiceTitles();
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  const nodes: Text[] = [];
  while (walker.nextNode()) nodes.push(walker.currentNode as Text);
  for (const node of nodes) {
    const source = node.nodeValue ?? "";
    const trimmed = source.trim();
    const translated = translations[trimmed];
    // Only write real changes: identical writes still fire the MutationObserver
    // below and would re-trigger this function forever (e.g. "Contact" → "Contact").
    if (translated && translated !== trimmed) {
      node.nodeValue = source.replace(trimmed, translated);
      continue;
    }
    // Numbered section headings render as one text node: "02 / What we build".
    const numbered = /^(\d{2} \/ )(.+)$/.exec(trimmed);
    const rest = numbered ? translations[numbered[2]] : undefined;
    if (rest && rest !== numbered[2]) node.nodeValue = source.replace(trimmed, numbered[1] + rest);
  }

  document.querySelectorAll<HTMLElement>("[aria-label], [aria-description], [title], [placeholder], img[alt]").forEach((element) => {
    for (const attribute of ["aria-label", "aria-description", "title", "placeholder", "alt"]) {
      if (attribute === "aria-label" && element.classList.contains("oveliq-split")) continue;
      const value = element.getAttribute(attribute);
      if (!value) continue;
      const progressLabel = /^Service (\d+) of (\d+)$/.exec(value);
      const translated = translations[value]
        ?? (progressLabel ? `Service ${progressLabel[1]} sur ${progressLabel[2]}` : undefined)
        ?? (value.startsWith("Explore ") ? `Découvrir ${value.slice("Explore ".length)}` : undefined);
      if (translated && translated !== value) element.setAttribute(attribute, translated);
    }
  });

  document.querySelectorAll<HTMLElement>(".oveliq-split[aria-label]").forEach((element) => {
    const source = element.getAttribute("aria-label") ?? "";
    const translated = translations[source];
    if (!translated || translated === source) return;
    element.setAttribute("aria-label", translated);
    const words = translated.split(/\s+/);
    const units = element.querySelectorAll<HTMLElement>(".oveliq-split__unit");
    units.forEach((unit, index) => {
      unit.textContent = index < units.length - 1 ? (words[index] ?? "") : words.slice(index).join(" ");
    });
  });

  document.querySelectorAll<HTMLAnchorElement>("a[href]").forEach((link) => {
    const url = new URL(link.href, window.location.origin);
    // The language switch deliberately points at the English page; leave it alone.
    if (link.hasAttribute("data-locale-switch")) return;
    if (url.origin !== window.location.origin || url.pathname.startsWith("/fr")) return;
    const routes: Record<string, string> = {
      "/": "/fr", "/work": "/fr/projets", "/services": "/fr/services", "/pricing": "/fr/tarifs",
      "/about": "/fr/a-propos", "/contact": "/fr/contact", "/privacy": "/fr/confidentialite", "/terms": "/fr/conditions",
    };
    if (routes[url.pathname]) url.pathname = routes[url.pathname];
    else if (url.pathname.startsWith("/work/")) url.pathname = url.pathname.replace("/work/", "/fr/projets/");
    else if (url.pathname.startsWith("/services/")) url.pathname = url.pathname.replace("/services/", "/fr/services/");
    else return;
    const localized = `${url.pathname}${url.search}${url.hash}`;
    if (link.getAttribute("href") !== localized) link.setAttribute("href", localized);
  });
}

function FrenchContent({ children }: { children: ReactNode }) {
  useEffect(() => {
    localizeVisibleCopy();
    const observer = new MutationObserver(localizeVisibleCopy);
    observer.observe(document.body, { childList: true, subtree: true, characterData: true });
    return () => observer.disconnect();
  }, []);
  return <>{children}</>;
}

export default function FrenchPage({ section = "", slug }: { section?: string; slug?: string }) {
  let page: ReactNode;
  if (section === "projets" && slug) {
    const project = findProjectDetail(slug);
    page = project ? <ProjectPage project={project} /> : <WorkPage />;
  } else if (section === "projets") page = <WorkPage />;
  else if (section === "services" && slug) {
    const service = findServicePage(slug);
    page = service ? <ServicePage page={service} /> : <ServicesPage />;
  } else if (section === "services") page = <ServicesPage />;
  else if (section === "tarifs") page = <PricingPage />;
  else if (section === "a-propos") page = <AboutPage />;
  else if (section === "contact") page = <ContactPage locale="fr" />;
  else if (section === "confidentialite") page = <LegalPage page={oveliqPrivacyPage} />;
  else if (section === "conditions") page = <LegalPage page={oveliqTermsPage} />;
  else page = <Page />;
  return <FrenchContent>{page}</FrenchContent>;
}
